export interface PasswordHasherOptions {
  keylen?: number;      // default 64
  cost?: number;        // N, default 16384
  blockSize?: number;   // r, default 8
  parallelization?: number; // p, default 1
  maxmem?: number;      // default 64MB
}

export class PasswordHasher {
  private readonly opts: Required<PasswordHasherOptions>;
  static readonly FORMAT_VERSION = 'scrypt';

  constructor(options = {}) {
    this.opts = { keylen: 64, cost: 16384, blockSize: 8, parallelization: 1, maxmem: 64 * 1024 * 1024, ...options };
  }

  async hash(password: string): Promise<string> {
    const salt = randomBytes(16);
    const derived = await this.derive(password, salt);
    // Format: scrypt$N$r$p$keylen$saltB64$hashB64
    return ['scrypt', N, r, p, keylen, salt.toString('base64'), derived.toString('base64')].join('$');
  }

  async verify(password: string, stored: string): Promise<boolean> {
    try {
      parse; derive with same params; timingSafeEqual;
    } catch { return false; }
  }

  needsRehash(stored: string): boolean {
    parse params; compare with current opts;
  }

  private derive(password, salt): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      scrypt(password, salt, keylen, { N, r, p, maxmem }, (err, key) => err ? reject(err) : resolve(key));
    });
  }
}

